import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';

const RegisterPage = () => {
  const [formData, setFormData] = useState({
    robloxUserId: '',
    robloxUsername: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Validate inputs
    if (!formData.robloxUserId.trim()) {
      setError('Please enter your Roblox User ID');
      setLoading(false);
      return;
    }

    if (!formData.robloxUsername.trim()) {
      setError('Please enter your Roblox Username');
      setLoading(false);
      return;
    }

    if (!formData.password.trim()) {
      setError('Please enter a password');
      setLoading(false);
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }

    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters long');
      setLoading(false);
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/auth/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          robloxUserId: formData.robloxUserId,
          robloxUsername: formData.robloxUsername,
          password: formData.password
        }),
      });

      const data = await response.json();

      if (response.ok) {
        // Store token and user data
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));

        // Navigate to dashboard
        navigate('/coinflip');
      } else {
        setError(data.message || 'Registration failed');
      }
    } catch (err) {
      console.error('Registration error:', err);
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <form onSubmit={handleSubmit} className="auth-form">
        <h2>Register</h2>

        <div style={{display: 'flex', alignItems: 'center', color: '#ff4d4d', marginBottom: '15px', fontSize: '14px'}}>
          <span style={{color: '#ff4d4d', marginRight: '8px'}}>●</span>
          <span>Please use your actual roblox username we are not responsible if you use a different username in any loss of items</span>
        </div>

        {error && <div className="error-message" style={{color: '#ff4d4d', marginBottom: '15px'}}>{error}</div>}

        <div className="form-group">
          <label htmlFor="robloxUserId" className="form-label">Roblox User ID</label>
          <input
            type="text"
            id="robloxUserId"
            name="robloxUserId"
            value={formData.robloxUserId}
            onChange={handleChange}
            className="form-control"
            placeholder="Enter your Roblox User ID"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="robloxUsername" className="form-label">Roblox Username</label>
          <input
            type="text"
            id="robloxUsername"
            name="robloxUsername"
            value={formData.robloxUsername}
            onChange={handleChange}
            className="form-control"
            placeholder="Enter your Roblox Username"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="password" className="form-label">Password</label>
          <input
            type="password"
            id="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            className="form-control"
            placeholder="Enter your password"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="confirmPassword" className="form-label">Confirm Password</label>
          <input
            type="password"
            id="confirmPassword"
            name="confirmPassword"
            value={formData.confirmPassword}
            onChange={handleChange}
            className="form-control"
            placeholder="Confirm your password"
            required
          />
        </div>

        <button 
          type="submit" 
          className="btn btn-primary"
          disabled={loading}
        >
          {loading ? 'Registering...' : 'Register'}
        </button>

        <div className="auth-links">
          <p>
            Already have an account? <Link to="/login">Login</Link>
          </p>
        </div>
      </form>
    </div>
  );
};

export default RegisterPage;
